<script setup>defineProps({task:Object});const emit=defineEmits(['toggle','delete'])</script><template><article class="task" :class="{completed:task.done}"><button class="check" @click="emit('toggle',task.id)">{{task.done?'✓':'○'}}</button><div class="task-copy"><b>{{task.title}}</b><small><span class="tag">{{task.category}}</span>　◷ {{task.minutes}} 分钟</small></div><span v-if="task.done" class="done-label">已完成</span><button class="delete" aria-label="删除任务" @click="emit('delete',task.id)">×</button></article></template>